PRAGMA user_version = 1;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, sha256 TEXT NOT NULL CHECK(length(sha256)=64));
CREATE TABLE study(id TEXT PRIMARY KEY, title TEXT NOT NULL, source_digest TEXT NOT NULL);
CREATE TABLE subsystem(id TEXT PRIMARY KEY, lane TEXT NOT NULL CHECK(lane IN ('runtime','state','infra')), owner TEXT NOT NULL);
CREATE TABLE reference(id TEXT PRIMARY KEY, revision TEXT NOT NULL, locator TEXT NOT NULL, qualification TEXT NOT NULL);
CREATE TABLE hypothesis(id TEXT PRIMARY KEY, subsystem_id TEXT NOT NULL REFERENCES subsystem, question TEXT NOT NULL, disposition TEXT NOT NULL CHECK(disposition IN ('accepted','deferred','rejected')), limitation TEXT NOT NULL);
CREATE TABLE hypothesis_reference(hypothesis_id TEXT REFERENCES hypothesis, reference_id TEXT REFERENCES reference, PRIMARY KEY(hypothesis_id,reference_id));
CREATE TABLE source_revision(id TEXT PRIMARY KEY, git_sha TEXT NOT NULL CHECK(length(git_sha)=40), lock_sha256 TEXT, version TEXT NOT NULL, qualification TEXT NOT NULL);
CREATE TABLE build(id TEXT PRIMARY KEY, source_id TEXT REFERENCES source_revision, image TEXT NOT NULL, compiler TEXT, flags TEXT NOT NULL, allocator TEXT NOT NULL, binary_sha256 TEXT CHECK(binary_sha256 IS NULL OR length(binary_sha256)=64), symbols_sha256 TEXT CHECK(symbols_sha256 IS NULL OR length(symbols_sha256)=64));
CREATE TABLE provider_set(id TEXT PRIMARY KEY, qualification TEXT NOT NULL);
CREATE TABLE provider(id TEXT PRIMARY KEY, sha256 TEXT CHECK(sha256 IS NULL OR length(sha256)=64), bytes INTEGER CHECK(bytes>0), manifest_bytes INTEGER CHECK(manifest_bytes>=0));
CREATE TABLE provider_member(set_id TEXT REFERENCES provider_set, ordinal INTEGER CHECK(ordinal>=0), provider_id TEXT REFERENCES provider, PRIMARY KEY(set_id,ordinal), UNIQUE(set_id,provider_id));
CREATE TABLE factor(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('integer','real','text','boolean')), unit TEXT NOT NULL);
CREATE TABLE factor_level(factor_id TEXT REFERENCES factor, id TEXT NOT NULL, kind TEXT NOT NULL, integer_value INTEGER, real_value REAL, text_value TEXT, PRIMARY KEY(factor_id,id), CHECK((kind='integer' AND integer_value IS NOT NULL AND real_value IS NULL AND text_value IS NULL) OR (kind='boolean' AND integer_value IS NOT NULL AND integer_value IN (0,1) AND real_value IS NULL AND text_value IS NULL) OR (kind='real' AND real_value IS NOT NULL AND integer_value IS NULL AND text_value IS NULL) OR (kind='text' AND text_value IS NOT NULL AND integer_value IS NULL AND real_value IS NULL)));
CREATE TRIGGER typed_level BEFORE INSERT ON factor_level WHEN NEW.kind != (SELECT kind FROM factor WHERE id=NEW.factor_id) BEGIN SELECT RAISE(ABORT,'factor kind mismatch'); END;
CREATE TABLE recipe(id TEXT PRIMARY KEY, implementation TEXT NOT NULL, classification TEXT NOT NULL CHECK(classification IN ('infra','release-replica','source-kernel','library','prototype','unsupported')), timeout_s INTEGER NOT NULL CHECK(timeout_s BETWEEN 1 AND 180), memory_bytes INTEGER NOT NULL CHECK(memory_bytes BETWEEN 33554432 AND 1073741824), pids INTEGER NOT NULL CHECK(pids BETWEEN 4 AND 128), cpus REAL NOT NULL CHECK(cpus>0 AND cpus<=2), output_bytes INTEGER NOT NULL CHECK(output_bytes BETWEEN 1024 AND 16777216));
CREATE TABLE experiment(id TEXT PRIMARY KEY, study_id TEXT NOT NULL REFERENCES study, hypothesis_id TEXT REFERENCES hypothesis, lane TEXT NOT NULL CHECK(lane IN ('runtime','state','infra')), stage INTEGER NOT NULL CHECK(stage BETWEEN 0 AND 3), priority INTEGER NOT NULL CHECK(priority>=0), recipe_id TEXT NOT NULL REFERENCES recipe, build_id TEXT REFERENCES build, provider_set_id TEXT REFERENCES provider_set, status TEXT NOT NULL CHECK(status IN ('planned','ready','unsupported','blocked','skipped')), reason TEXT NOT NULL, config_json TEXT NOT NULL CHECK(json_valid(config_json)));
CREATE TABLE assignment(experiment_id TEXT REFERENCES experiment, factor_id TEXT NOT NULL, level_id TEXT NOT NULL, PRIMARY KEY(experiment_id,factor_id), FOREIGN KEY(factor_id,level_id) REFERENCES factor_level(factor_id,id));
CREATE TABLE comparison_group(id TEXT PRIMARY KEY, question TEXT NOT NULL, required_replicates INTEGER NOT NULL DEFAULT 3 CHECK(required_replicates>=3));
CREATE TABLE comparison_member(group_id TEXT REFERENCES comparison_group, experiment_id TEXT REFERENCES experiment, role TEXT NOT NULL CHECK(role IN ('baseline','control','variant')), PRIMARY KEY(group_id,experiment_id));
CREATE TABLE prerequisite(id TEXT PRIMARY KEY, description TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('implemented','artifact','trial','manual')));
CREATE TABLE experiment_prerequisite(experiment_id TEXT REFERENCES experiment, prerequisite_id TEXT REFERENCES prerequisite, PRIMARY KEY(experiment_id,prerequisite_id));
CREATE TABLE prerequisite_evidence(prerequisite_id TEXT PRIMARY KEY REFERENCES prerequisite, satisfied INTEGER NOT NULL CHECK(satisfied IN (0,1)), evidence TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE experiment_dependency(experiment_id TEXT REFERENCES experiment, predecessor_id TEXT REFERENCES experiment, PRIMARY KEY(experiment_id,predecessor_id), CHECK(experiment_id!=predecessor_id));
CREATE TABLE environment(id TEXT PRIMARY KEY, os TEXT NOT NULL, architecture TEXT NOT NULL, page_bytes INTEGER CHECK(page_bytes>0), libc TEXT, daemon_id TEXT NOT NULL, limits_json TEXT NOT NULL CHECK(json_valid(limits_json)), load_json TEXT NOT NULL CHECK(json_valid(load_json)), filesystem TEXT, tool_versions_json TEXT NOT NULL CHECK(json_valid(tool_versions_json)));
CREATE TABLE campaign(id TEXT PRIMARY KEY, created_at TEXT NOT NULL, seed INTEGER NOT NULL, driver_sha256 TEXT NOT NULL CHECK(length(driver_sha256)=64), status TEXT NOT NULL CHECK(status IN ('open','closed')));
CREATE TABLE trial(id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaign, experiment_id TEXT NOT NULL REFERENCES experiment, replicate INTEGER NOT NULL CHECK(replicate BETWEEN 1 AND 3), order_index INTEGER NOT NULL CHECK(order_index>=0), pair_id TEXT REFERENCES trial, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','blocked','skipped','interrupted','failed','succeeded')), UNIQUE(campaign_id,experiment_id,replicate), UNIQUE(campaign_id,order_index));
CREATE TABLE attempt(id TEXT PRIMARY KEY, trial_id TEXT NOT NULL REFERENCES trial, number INTEGER NOT NULL CHECK(number BETWEEN 1 AND 2), previous_id TEXT REFERENCES attempt, status TEXT NOT NULL CHECK(status IN ('claimed','running','blocked','interrupted','failed','succeeded','attention')), started_at TEXT NOT NULL, ended_at TEXT, environment_id TEXT REFERENCES environment, driver_sha256 TEXT NOT NULL CHECK(length(driver_sha256)=64), condition_sha256 TEXT NOT NULL CHECK(length(condition_sha256)=64), command_json TEXT NOT NULL CHECK(json_valid(command_json)), parser_id TEXT NOT NULL, exit_code INTEGER, signal INTEGER, cancel_requested INTEGER NOT NULL DEFAULT 0 CHECK(cancel_requested IN (0,1)), free_before_bytes INTEGER CHECK(free_before_bytes>=0), free_after_bytes INTEGER CHECK(free_after_bytes>=0), UNIQUE(trial_id,number), CHECK((number=1 AND previous_id IS NULL) OR (number=2 AND previous_id IS NOT NULL)));
CREATE TRIGGER retry_link BEFORE INSERT ON attempt WHEN NEW.number=2 AND NOT EXISTS(SELECT 1 FROM attempt a WHERE a.id=NEW.previous_id AND a.trial_id=NEW.trial_id AND a.number=1 AND a.condition_sha256=NEW.condition_sha256 AND a.driver_sha256=NEW.driver_sha256 AND a.status IN ('failed','interrupted','blocked')) BEGIN SELECT RAISE(ABORT,'retry must preserve condition and predecessor'); END;
CREATE TABLE executor_identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1), uuid TEXT NOT NULL, driver_sha256 TEXT NOT NULL, db_device INTEGER NOT NULL, db_inode INTEGER NOT NULL);
CREATE TABLE slot(id INTEGER PRIMARY KEY CHECK(id IN (1,2)), attempt_id TEXT UNIQUE REFERENCES attempt, token TEXT UNIQUE, heartbeat_at TEXT, CHECK((attempt_id IS NULL AND token IS NULL AND heartbeat_at IS NULL) OR (attempt_id IS NOT NULL AND token IS NOT NULL AND heartbeat_at IS NOT NULL)));
INSERT INTO slot(id) VALUES(1),(2);
CREATE TRIGGER keep_slots BEFORE DELETE ON slot BEGIN SELECT RAISE(ABORT,'fixed global slots'); END;
CREATE TABLE resource(attempt_id TEXT PRIMARY KEY REFERENCES attempt, token TEXT NOT NULL UNIQUE, daemon_id TEXT NOT NULL, container_name TEXT NOT NULL UNIQUE, container_id TEXT UNIQUE, created_at TEXT, started_at TEXT, volume_name TEXT NOT NULL UNIQUE, drained_at TEXT);
CREATE TABLE error(id INTEGER PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempt, category TEXT NOT NULL CHECK(category IN ('transient','missing-dependency','unsafe-prerequisite','resource-exhaustion','fixture-parser','benchmark','interrupted','ownership')), message TEXT NOT NULL, retryable INTEGER NOT NULL CHECK(retryable IN (0,1)), at TEXT NOT NULL);
CREATE TABLE recovery(id INTEGER PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempt, decision TEXT NOT NULL CHECK(decision IN ('refused','drained','attention')), reason TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE artifact(id TEXT PRIMARY KEY, attempt_id TEXT REFERENCES attempt, kind TEXT NOT NULL, relative_path TEXT NOT NULL UNIQUE CHECK(relative_path NOT LIKE '/%' AND relative_path NOT LIKE '%..%'), sha256 TEXT NOT NULL CHECK(length(sha256)=64), bytes INTEGER NOT NULL CHECK(bytes>=0), privacy TEXT NOT NULL CHECK(privacy IN ('private','sanitized')), created_at TEXT NOT NULL);
CREATE TRIGGER immutable_artifact BEFORE UPDATE ON artifact BEGIN SELECT RAISE(ABORT,'immutable evidence'); END;
CREATE TRIGGER retained_artifact BEFORE DELETE ON artifact BEGIN SELECT RAISE(ABORT,'retain evidence'); END;
CREATE TABLE metric(id TEXT PRIMARY KEY, unit TEXT NOT NULL, definition TEXT NOT NULL, aggregation TEXT NOT NULL CHECK(aggregation IN ('gauge','counter','duration')));
CREATE TABLE parse_run(id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempt, parser_sha256 TEXT NOT NULL CHECK(length(parser_sha256)=64), input_artifact_id TEXT NOT NULL REFERENCES artifact, at TEXT NOT NULL, supersedes TEXT REFERENCES parse_run);
CREATE TABLE sample(parse_id TEXT REFERENCES parse_run, ordinal INTEGER NOT NULL CHECK(ordinal>=0), phase TEXT NOT NULL, elapsed_ns INTEGER NOT NULL CHECK(elapsed_ns>=0), metric_id TEXT NOT NULL REFERENCES metric, value REAL NOT NULL CHECK(value>=0 AND value<1e100), PRIMARY KEY(parse_id,ordinal,metric_id));
CREATE TABLE phase_summary(parse_id TEXT REFERENCES parse_run, phase TEXT NOT NULL, metric_id TEXT REFERENCES metric, n INTEGER NOT NULL CHECK(n>0), minimum REAL NOT NULL, maximum REAL NOT NULL, mean REAL NOT NULL, p50 REAL NOT NULL, p95 REAL NOT NULL, PRIMARY KEY(parse_id,phase,metric_id));
CREATE TABLE missing_metric(attempt_id TEXT REFERENCES attempt, metric_id TEXT REFERENCES metric, reason TEXT NOT NULL, PRIMARY KEY(attempt_id,metric_id));
CREATE TABLE cleanup(id INTEGER PRIMARY KEY, attempt_id TEXT REFERENCES attempt, target TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('refused','retained','removed','drained')), reason TEXT NOT NULL, free_before_bytes INTEGER, free_after_bytes INTEGER, at TEXT NOT NULL);
CREATE TABLE finding(id TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('source-supported','observed','inferred','unknown')), claim TEXT NOT NULL, limitation TEXT NOT NULL);
CREATE TABLE finding_evidence(finding_id TEXT REFERENCES finding, reference_id TEXT REFERENCES reference, artifact_id TEXT REFERENCES artifact, parse_id TEXT REFERENCES parse_run, CHECK((reference_id IS NOT NULL)+(artifact_id IS NOT NULL)+(parse_id IS NOT NULL)=1), UNIQUE(finding_id,reference_id,artifact_id,parse_id));
CREATE TABLE proposed_control(id TEXT PRIMARY KEY, owner TEXT NOT NULL, scope TEXT NOT NULL, unit TEXT NOT NULL, ceiling TEXT NOT NULL CHECK(ceiling IN ('hard','soft')), pressure_response TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Current','Committed direction','Exploration')), tradeoff TEXT NOT NULL);
CREATE TABLE followup(id TEXT PRIMARY KEY, hypothesis_id TEXT REFERENCES hypothesis, question TEXT NOT NULL, expected_gain TEXT NOT NULL, safe_recipe TEXT NOT NULL, bound TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','blocked','done')));
CREATE TABLE followup_dependency(followup_id TEXT REFERENCES followup, experiment_id TEXT REFERENCES experiment, PRIMARY KEY(followup_id,experiment_id));
CREATE VIEW matrix AS SELECT e.id,e.lane,e.stage,e.priority,e.status,e.reason,e.hypothesis_id,r.classification,e.recipe_id,a.factor_id,l.kind,l.integer_value,l.real_value,l.text_value,f.unit FROM experiment e JOIN recipe r ON r.id=e.recipe_id LEFT JOIN assignment a ON a.experiment_id=e.id LEFT JOIN factor_level l ON l.factor_id=a.factor_id AND l.id=a.level_id LEFT JOIN factor f ON f.id=a.factor_id;
CREATE VIEW coverage AS SELECT e.id,e.lane,e.stage,e.status AS cell_status,r.classification,COUNT(t.id) AS trials,SUM(CASE WHEN t.status='succeeded' THEN 1 ELSE 0 END) AS succeeded, e.reason FROM experiment e JOIN recipe r ON r.id=e.recipe_id LEFT JOIN trial t ON t.experiment_id=e.id GROUP BY e.id;
CREATE VIEW latest_parse AS SELECT p.* FROM parse_run p WHERE NOT EXISTS(SELECT 1 FROM parse_run n WHERE n.supersedes=p.id);
CREATE VIEW results AS SELECT t.campaign_id,t.experiment_id,t.replicate,a.id AS attempt_id,a.status,e.architecture,e.page_bytes,s.*,m.unit FROM phase_summary s JOIN latest_parse p ON p.id=s.parse_id JOIN attempt a ON a.id=p.attempt_id JOIN trial t ON t.id=a.trial_id LEFT JOIN environment e ON e.id=a.environment_id JOIN metric m ON m.id=s.metric_id;
CREATE VIEW unresolved AS SELECT e.id,e.lane,e.reason,p.id AS prerequisite,p.description,COALESCE(v.satisfied,0) AS satisfied FROM experiment e LEFT JOIN experiment_prerequisite ep ON ep.experiment_id=e.id LEFT JOIN prerequisite p ON p.id=ep.prerequisite_id LEFT JOIN prerequisite_evidence v ON v.prerequisite_id=p.id;
